parameters.jsCode:
const raw = $input.first().json.message?.content || '{}';
const contact = $('LOGIC — Split por Contacto').first().json;
let email;
try { email = JSON.parse(raw.match(/\{[\s\S]*\}/)?.[0] || raw); } catch(e) { return []; }
if (!email.subject || !email.body_html) return [];
email.to = contact.email;
email.contact_id = contact.id || contact.email;
email.segment = contact.segment;
email.campaign_id = $('DATA — Cargar Segmentos CRM').first().json.campaign_id;
email.ab_variant = Math.random() < 0.5 ? 'A' : 'B';
return [{ json: email }];
